data.query:
query Query($where: ProductionSetupBOMWhereInput, $orderBy: [ProductionSetupBOMOrderByInput!], $first: Int, $after: String) {
  bom:productionSetupBOM(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    total
    edges {
      node {
        id
        consumptionMode {
          name
          actualUsage
        }
      }
    }
  }
}

query Query($where: ProductionSetupOutputWhereInput, $orderBy: [ProductionSetupOutputOrderByInput!], $first: Int, $after: String) {
  productionSetupOutput(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
    producedQuantity
    scrappedQuantity
    remainingBalance

      }
    }
  }
}

data.mutation:
mutation Mutation($payload: [WorkOrderProcessUpdatePayloadInput!]!) {
  updateWorkOrderProcess(payload: $payload) {
    id
    code
    quantity
    externalId
    workOrderProcessStatusId
  }
}

